const clinicas = $input.all();

if (clinicas.length === 0) {
  return [{ json: { query: null, mensaje: 'No hay clínicas activas' } }];
}

const queries = clinicas.map(c => {
  const schema = c.json.schema_name;
  return `SELECT '${c.json.clinica_id}' as clinica_id, '${schema}' as schema_name, * FROM ${schema}.conversaciones WHERE estado = 'agendado'`;
});

const query = queries.join(' UNION ALL ') + ';';

return [{ json: { query } }];

